{"command":"python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('Reopened:', path)
print('Sheets:', wb.sheetnames)
ws=wb['Task']
expected_sheets=['Task','Data']
print('Sheet check:', wb.sheetnames == expected_sheets)
# Print target formula cells
ranges=['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
for rng in ranges:
    print('\nRange', rng)
    for row in ws[rng]:
        print(' | '.join(f'{cell.coordinate}={cell.value}' for cell in row))
# Validate formulas and no missing target cells
errors=[]
for r in list(range(12,18)) + list(range(19,25)) + list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
for r in range(35,41):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{r-23}-{col}{r-16})/{col}{r-9}*100'
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
stat_exps={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for r in range(42,48):
    for c in range(8,13):
        col=get_column_letter(c)
        if r in stat_exps:
            exp=f'={stat_exps[r]}({col}$35:{col}$40)'
        elif r == 46:
            exp=f'=PERCENTILE.INC({col}$35:{col}$40,0.25)'
        else:
            exp=f'=PERCENTILE.INC({col}$35:{col}$40,0.75)'
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
for c in range(8,13):
    col=get_column_letter(c)
    exp=f'=SUMPRODUCT({col}$35:{col}$40,{col}$26:{col}$31)/SUM({col}$26:{col}$31)'
    if ws.cell(50,c).value != exp:
        errors.append((ws.cell(50,c).coordinate, ws.cell(50,c).value, exp))
print('\nFormula validation errors:', len(errors))
for e in errors[:20]: print(e)
if wb.sheetnames != expected_sheets or errors:
    raise SystemExit(1)
